import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Recommend from './pages/Recommend';
import BestTime from './pages/BestTime';

function App() {
  return (
    <BrowserRouter>
      <div className="min-h-screen bg-background text-primary">
        <nav className="bg-primary text-white p-4 flex justify-between items-center">
          <h1 className="text-xl font-bold">🌿 PlantSmart</h1>
          <div className="space-x-4">
            <a href="/" className="hover:text-secondary">Recommend Crop</a>
            <a href="/best-time" className="hover:text-secondary">Best Time</a>
          </div>
        </nav>
        <Routes>
          <Route path="/" element={<Recommend />} />
          <Route path="/best-time" element={<BestTime />} />
        </Routes>
      </div>
    </BrowserRouter>
  );
}

export default App;
